import { PROVENANCE_POSITION } from "./provenance.js";

const safe = (value) => String(value).replace(/[<>]/g, "");

export const GENERATED_SHADER_NOTICE = `Generated by This Shader Does Not Exist (TSDNE).
TSDNE retains provenance but abolishes title.
The shader can be identified, copied, and reconstructed, but not claimed.
This technical information creates no ownership, exclusivity, scarcity, authenticity, or uniqueness right.
To the extent that the TSDNE project holds waivable rights in this generated output, those rights are waived under CC0 1.0.
The authored TSDNE generator and application are separately licensed under GPL-3.0-or-later.`;

function vertexGLSL3() {
  return `#version 300 es
in vec2 a_position;
void main(){gl_Position=vec4(a_position,0.0,1.0);}`;
}

export function technicalManifest(candidate) {
  if (!candidate.provenance) throw new Error("Internal provenance must be attached before export.");
  return {
    schema: "tsdne-technical-manifest-v1",
    documentType: "technical-manifest-not-certificate",
    generatorVersion: candidate.provenance.generatorVersion,
    family: candidate.family,
    seed: candidate.seed,
    graph: candidate.graph,
    sourceHash: candidate.provenance.sourceHash,
    graphHash: candidate.provenance.graphHash,
    source: candidate.source,
    position: PROVENANCE_POSITION,
    licensing: {
      application: "GPL-3.0-or-later",
      generatedOutputIntent: "CC0-1.0 to the extent waivable rights exist",
    },
    notice: GENERATED_SHADER_NOTICE,
  };
}

export function rawGLSL(candidate) {
  return `/*
${GENERATED_SHADER_NOTICE}
Generator: ${candidate.provenance?.generatorVersion || "unknown"}
Source SHA-256: ${candidate.provenance?.sourceHash || "unavailable"}
*/
${candidate.source}`;
}

export function selfContainedHTML(candidate) {
  const source = JSON.stringify(candidate.source);
  const vertex = JSON.stringify(vertexGLSL3());
  const notice = GENERATED_SHADER_NOTICE.replaceAll("--", "—");
  return `<!doctype html>
<!--
${notice}
Source SHA-256: ${safe(candidate.provenance?.sourceHash || "unavailable")}
-->
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TSDNE shader</title><style>html,body,canvas{width:100%;height:100%;margin:0;display:block;background:#000}</style><canvas aria-label="Generated TSDNE shader"></canvas><script>const canvas=document.querySelector('canvas'),gl=canvas.getContext('webgl2');if(!gl)throw Error('WebGL2 required');const compile=(t,s)=>{const x=gl.createShader(t);gl.shaderSource(x,s);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(x));return x};const p=gl.createProgram();gl.attachShader(p,compile(gl.VERTEX_SHADER,${vertex}));gl.attachShader(p,compile(gl.FRAGMENT_SHADER,${source}));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const pos=gl.getAttribLocation(p,'a_position'),res=gl.getUniformLocation(p,'u_resolution'),time=gl.getUniformLocation(p,'u_time'),motion=gl.getUniformLocation(p,'u_motion'),intensity=gl.getUniformLocation(p,'u_intensity'),start=performance.now();function frame(now){const d=Math.min(devicePixelRatio||1,2),w=Math.floor(innerWidth*d),h=Math.floor(innerHeight*d);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}gl.viewport(0,0,w,h);gl.useProgram(p);gl.enableVertexAttribArray(pos);gl.vertexAttribPointer(pos,2,gl.FLOAT,false,0,0);gl.uniform2f(res,w,h);gl.uniform1f(time,(now-start)/1000);if(motion)gl.uniform1f(motion,1);if(intensity)gl.uniform1f(intensity,1);gl.drawArrays(gl.TRIANGLES,0,3);requestAnimationFrame(frame)}requestAnimationFrame(frame);<\/script>`;
}

export function threeJS(candidate) {
  const fragment = candidate.source.replace(/^#version 300 es\n/, "");
  return `// ${GENERATED_SHADER_NOTICE.replaceAll("\n", "\n// ")}
import * as THREE from 'three';

export const uniforms = {
  u_resolution: { value: new THREE.Vector2() },
  u_time: { value: 0 },
  u_motion: { value: 1 },
  u_intensity: { value: 1 },
};

export const material = new THREE.RawShaderMaterial({
  glslVersion: THREE.GLSL3,
  uniforms,
  vertexShader: \`in vec3 position;
void main(){gl_Position=vec4(position.xy,0.0,1.0);}\`,
  fragmentShader: ${JSON.stringify(fragment)},
});
`;
}

export function shaderToy(candidate) {
  let body = candidate.source
    .replace(/^#version 300 es\n/, "")
    .replace("out vec4 outColor;\n", "")
    .replace("uniform vec2 u_resolution;\n", "#define u_resolution iResolution.xy\n")
    .replace("uniform float u_time;\n", "#define u_time iTime\n")
    .replace("uniform float u_motion;\n", "#define u_motion 1.0\n")
    .replace("uniform float u_intensity;\n", "#define u_intensity 1.0\n");
  body = body
    .replace(/void main\(\)\s*\{/, "void mainImage(out vec4 outColor, in vec2 fragCoord){")
    .replaceAll("gl_FragCoord.xy", "fragCoord");
  return `// ${GENERATED_SHADER_NOTICE.replaceAll("\n", "\n// ")}\n${body}`;
}

export function isf(candidate) {
  const fragment = candidate.source
    .replace(/^#version 300 es\n/, "")
    .replace("out vec4 outColor;\n", "")
    .replace("uniform vec2 u_resolution;\n", "#define u_resolution RENDERSIZE\n")
    .replace("uniform float u_time;\n", "#define u_time TIME\n")
    .replace("uniform float u_motion;\n", "#define u_motion 1.0\n")
    .replace("uniform float u_intensity;\n", "#define u_intensity 1.0\n")
    .replaceAll("outColor", "gl_FragColor");
  return `/*{\"DESCRIPTION\":\"TSDNE generated shader\",\"CREDIT\":\"Generated output: CC0 waiver to the extent waivable rights exist\",\"CATEGORIES\":[\"Generator\"],\"INPUTS\":[]}*/\n${fragment}`;
}

export function exportFiles(candidate) {
  return {
    "tsdne-manifest.json": JSON.stringify(technicalManifest(candidate), null, 2),
    "tsdne-shader.frag": rawGLSL(candidate),
    "tsdne-shader.html": selfContainedHTML(candidate),
    "tsdne-three.js": threeJS(candidate),
    "tsdne-shadertoy.glsl": shaderToy(candidate),
    "tsdne-shader.fs": isf(candidate),
  };
}

export function downloadText(filename, text, type = "text/plain") {
  const blob = new Blob([text], { type });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}
